CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS members (id TEXT PRIMARY KEY, discord_id TEXT UNIQUE, display_name TEXT, avatar_hash TEXT, membership_status TEXT NOT NULL, verified_at TEXT, deleted_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS member_roles (member_id TEXT NOT NULL REFERENCES members(id), role TEXT NOT NULL CHECK(role = 'administrator'), assigned_at TEXT NOT NULL, revoked_at TEXT, PRIMARY KEY(member_id, role, assigned_at));
CREATE TABLE IF NOT EXISTS sessions (id_hash TEXT PRIMARY KEY, member_id TEXT NOT NULL REFERENCES members(id), csrf_hash TEXT NOT NULL, expires_at TEXT NOT NULL, absolute_expires_at TEXT NOT NULL, last_seen_at TEXT NOT NULL, membership_verified_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT NOT NULL, description TEXT NOT NULL, category TEXT NOT NULL, starts_at_utc TEXT NOT NULL, ends_at_utc TEXT, timezone TEXT NOT NULL, max_participants INTEGER CHECK(max_participants > 0), status TEXT NOT NULL CHECK(status IN ('scheduled', 'cancelled', 'completed')), creator_member_id TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS event_rsvps (event_id TEXT NOT NULL REFERENCES events(id), member_id TEXT NOT NULL REFERENCES members(id), created_at TEXT NOT NULL, PRIMARY KEY(event_id, member_id));
